import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport '../../../core/providers/core_providers.dart';\nimport '../providers/homework_providers.dart';\nimport 'main_screen.dart';\n\nclass GradeSelectionScreen extends ConsumerWidget {\n  const GradeSelectionScreen({Key? key}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final localStorage = ref.watch(localStorageServiceProvider);\n    final schoolId = localStorage.getSchoolCode();\n\n    if (schoolId == null) {\n      return const Scaffold(body: Center(child: Text('خطأ: كود المدرسة مفقود')));\n    }\n\n    final classesAsync = ref.watch(classesProvider(schoolId));\n\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('اختر صفك الدراسي'),\n        centerTitle: true,\n      ),\n      body: classesAsync.when(\n        data: (classes) {\n          if (classes.isEmpty) {\n            return const Center(child: Text('لا توجد صفوف مضافة حالياً.'));\n          }\n          return ListView.builder(\n            padding: const EdgeInsets.all(16.0),\n            itemCount: classes.length,\n            itemBuilder: (context, index) {\n              final schoolClass = classes[index];\n              return Card(\n                elevation: 2,\n                margin: const EdgeInsets.only(bottom: 12),\n                child: ListTile(\n                  contentPadding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),\n                  title: Text(schoolClass.name, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),\n                  trailing: const Icon(Icons.arrow_forward_ios, color: Colors.blue),\n                  onTap: () async {\n                    await localStorage.saveSelectedGrade(schoolClass.id);\n                    if (!context.mounted) return;\n                    Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => const MainScreen()));\n                  },\n                ),\n              );\n            },\n          );\n        },\n        loading: () => const Center(child: CircularProgressIndicator()),\n        error: (err, stack) => Center(child: Text('حدث خطأ: $err')),\n      ),\n    );\n  }\n}\n